import { fileURLToPath } from 'node:url';
const { chromium } = await import(process.env.MX_PLAYWRIGHT_MODULE || 'playwright-core');import{mkdir,writeFile}from'node:fs/promises';
const out=fileURLToPath(new URL('../../docs/qa/layout-audit-2026-11-16', import.meta.url));await mkdir(`${out}/extra`,{recursive:true});
const browser=await chromium.launch({executablePath:process.env.MX_CHROME_PATH || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--mute-audio']});const results=[];
try{const p=await browser.newPage({viewport:{width:390,height:886},isMobile:true,hasTouch:true,deviceScaleFactor:1});
const cases=[...Array.from({length:7},(_,i)=>({scene:'empty',seats:i+2})),... [90,95,105].map(scale=>({scene:'actions',scale})),...[4,5].map(cards=>({scene:'revealed',cards})),{scene:'actions',quick:3},{scene:'actions',width:320,height:400,scale:110,raise:1},{scene:'actions',width:390,height:844,raise:1},{scene:'six',width:768,height:1024,scale:110},{scene:'actions',width:844,height:390,orientation:'auto'}];
for(const layout of ['original','balanced','oval','classic'])for(let i=0;i<cases.length;i++){const c={width:390,height:844,scale:100,...cases[i]},id=`${layout}-${i}-${c.scene}`;await p.setViewportSize({width:c.width,height:c.height+42});await p.goto('http://127.0.0.1:4179/tests/fixtures/layout-audit.html?'+new URLSearchParams({layout,...c}));await p.locator('#audit-stage[data-ready=true]').waitFor();let raise=null;if(c.raise){const b=await p.locator('.mx-operation-raise').boundingBox();await p.locator('.mx-operation-raise').click();const a=await p.locator('.mx-raise-confirm').boundingBox(),t=await p.locator('.mx-raise-track').boundingBox();raise={before:b,after:a,track:t,aligned:Math.max(...['x','y','width','height'].map(k=>Math.abs(a[k]-b[k])))<.1};}
await p.locator('#audit-stage').screenshot({path:`${out}/extra/${id}.jpg`,type:'jpeg',quality:82});const check=await p.evaluate(()=>{const root=document.querySelector('#audit-stage').getBoundingClientRect();const visible=s=>[...document.querySelectorAll(s)].filter(e=>e.getBoundingClientRect().width&&e.getClientRects().length);return {seats:visible('.mx-avatar-fallback').length,cards:visible('.mx-seat-mine .mx-card-slot').length,quick:visible('.mx-quick-bet').length,orientation:document.querySelector('.mx-table').dataset.orientation,outside:visible('.mx-card-slot,.mx-operation-button,.mx-player-name,.mx-stack,.mx-seat-hand-type').filter(e=>{const r=e.getBoundingClientRect();return r.left<root.left-1||r.right>root.right+1||r.top<root.top-1||r.bottom>root.bottom+1}).map(e=>({class:e.className,seat:e.closest('.mx-seat')?.dataset.seat,text:e.textContent}))};});results.push({id,layout,...c,raise,check});console.log(id,check.outside.length);}
await writeFile(`${out}/extra-metrics.json`,JSON.stringify(results,null,2));}finally{await browser.close();}
